import { DEFAULT_BANNER_SIZE, DEFAULT_BANNER_UPSELL_SIZE } from "../../banner/bannerUtils";
import { BannerUpsell } from "../../banner/bannerUpsell";
import { Banner } from "../../banner/banner";
export const convertBannerSizeToState = (banner) => {
    let { size } = banner.props;
    if (!size && banner.type === BannerUpsell) {
        size = DEFAULT_BANNER_UPSELL_SIZE;
    }
    if (!size && banner.type === Banner) {
        size = DEFAULT_BANNER_SIZE;
    }
    switch (size) {
        case "XXL":
        case "XL": {
            return {
                lg: 12
            };
        }
        default:
        case "L": {
            return {
                lg: 9
            };
        }
        case "M": {
            return {
                lg: 6
            };
        }
        case "S": {
            return {
                lg: 4
            };
        }
        case "XS": {
            return {
                lg: 2
            };
        }
    }
};
